async function enviar(evento) {
  evento.preventDefault();
  const limpio = titulo.trim();
  if (!limpio) { setError("Escribe un título"); return; }

  setEnviando(true);
  setError(null);
  try {
    const respuesta = await fetch("/api/practica/tareas", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ titulo: limpio }),
    });
    const cuerpo = await respuesta.json().catch(() => null);
    if (!respuesta.ok) { /* setError con cuerpo?.error */ return; }
    /* limpia el campo, aviso de éxito, alCrear?.(cuerpo) */
  } catch {
    setError("No se pudo conectar con el servidor");
  } finally {
    setEnviando(false);
  }
}

